SELECT i.* FROM pet_item i
WHERE i.del_flag = '0'

    AND (i.title LIKE CONCAT('%', #{keyword}, '%')
         OR i.brand LIKE CONCAT('%', #{keyword}, '%'))


    AND i.category_id IN
    #{cid}

AND i.audit_status = #{auditStatus}
AND i.status = #{status}
AND i.merchant_id = #{merchantId}
ORDER BY i.create_time DESC, i.id DESC
